// sm_80; one warp per output row; warpSize = 32
__global__ void gemv(const float* __restrict__ A,  // [M, K] row-major
                     const float* __restrict__ x,  // [K]
                     float* __restrict__ y,        // [M]
                     int M, int K) {
    int row = blockIdx.x;
    int lane = threadIdx.x;                 // 0..31
    float acc = 0.0f;
    for (int k = lane; k < K; k += 32) {
        acc += A[row * K + k] * x[k];
    }
    // warp reduction (assume warp_reduce_sum is defined as in F-REDUCE-011)
    acc = warp_reduce_sum(acc);
    if (lane == 0) y[row] = acc;
}
